        <button onClick={onCheckout} disabled={cart.length === 0} className="w-full py-4 bg-slate-900 text-white rounded-3xl font-black text-xl hover:bg-indigo-600 shadow-xl transition-all flex items-center justify-center disabled:opacity-50 active:scale-95">
           Charge {formatPrice(total)} <ChevronRight className="ml-2 w-6 h-6" />
        </button>
