    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, CartItem, EstimateResultItem, SystemSettings, Customer, Sale } from '../types';
import { Sparkles, User, ClipboardList, Monitor, ChevronRight } from 'lucide-react';
import { AiAssistant } from './AiAssistant';
import { BarcodeScanner } from './BarcodeScanner';
import { useGlobal } from '../context/GlobalContext';
import { useCartStore } from '../store/useCartStore';

// Sub-components
import { ProductGrid } from './pos/ProductGrid';
import { CartSidebar } from './pos/CartSidebar';
import { CheckoutModal } from './pos/CheckoutModal';
import { ReceiptModal } from './pos/ReceiptModal';
import { CustomerModal } from './pos/CustomerModal';
import { DiscountModal } from './pos/DiscountModal';
import { RecallModal } from './pos/RecallModal';
import { VariantSelectorModal } from './pos/VariantSelectorModal';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number,
    source?: 'pos' | 'back-office',
    roundingDifference?: number
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  const { customers, customerLevels, t, branches, warehouses, currentUser, formatPrice, categories } = useGlobal();
  const { 
    cart, addToCart, clearCart,
    heldOrders, holdCurrentOrder, recallOrder, discardHeldOrder
  } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false); 

  const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [isRecallModalOpen, setIsRecallModalOpen] = useState(false);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [productForSelector, setProductForSelector] = useState<Product | null>(null);

  const [manualDiscount, setManualDiscount] = useState<{ type: 'percent' | 'fixed', value: number } | null>(null);
  const [redeemPoints, setRedeemPoints] = useState<number>(0);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const activeBranchId = settings?.currentBranchId || currentUser?.branchId || (branches.length > 0 ? branches[0].id : '');

  const branchProducts = useMemo(() => {
    if (!activeBranchId) return products;
    const branchWarehouseIds = warehouses.filter(w => w.branchId === activeBranchId).map(w => w.id);
    return products.map(p => {
      const branchStock = p.warehouseInventory?.reduce((acc, inv) => branchWarehouseIds.includes(inv.warehouseId) ? acc + inv.quantity : acc, 0) || 0;
      const branchPriceConfig = p.branchPrices?.find(bp => bp.branchId === activeBranchId);
      return { ...p, stock: branchStock, price: branchPriceConfig ? branchPriceConfig.price : p.price };
    });
  }, [products, activeBranchId, warehouses]);

  const getDynamicPrice = (product: Product, variantId?: string): number => {
    let basePrice = product.price;
    let tierPrices = product.tierPrices;
    if (variantId && product.variants) {
      const variant = product.variants.find(v => v.id === variantId);
      if (variant) { basePrice = variant.price; tierPrices = variant.tierPrices || product.tierPrices; }
    }
    if (!selectedCustomer?.levelId) return basePrice;
    if (tierPrices && tierPrices[selectedCustomer.levelId]) return tierPrices[selectedCustomer.levelId];
    const level = customerLevels.find(l => l.id === selectedCustomer.levelId);
    return (level && level.discountPercentage > 0) ? basePrice * (1 - level.discountPercentage / 100) : basePrice;
  };

  const handleProductSelect = (product: Product) => {
    if (product.variants && product.variants.length > 0) setProductForSelector(product);
    else { const price = getDynamicPrice(product); addToCart({ ...product, price }, 1); }
  };

  const handleConfirmSelection = (product: Product, quantity: number, variantId?: string) => {
    const price = getDynamicPrice(product, variantId);
    addToCart({ ...product, price }, quantity, variantId);
    setProductForSelector(null);
  };

  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);
  let manualDiscountAmount = manualDiscount ? (manualDiscount.type === 'percent' ? rawSubtotal * (manualDiscount.value / 100) : manualDiscount.value) : 0;
  let discountAmount = Math.min(manualDiscountAmount, rawSubtotal);
  let discountedSubtotal = rawSubtotal - discountAmount;

  const isRoundingEnabled = settings?.rounding?.enabled ?? true;
  const roundingInterval = settings?.rounding?.interval || 500;
  const finalTotal = isRoundingEnabled ? Math.round(discountedSubtotal / roundingInterval) * roundingInterval : Math.round(discountedSubtotal * 100) / 100;
  const roundingDifference = finalTotal - discountedSubtotal;

  const handleProcessPayment = async (method: any, received: number, change: number) => {
    setIsProcessing(true);
    try {
      const sale = await onProcessSale(cart, finalTotal, selectedCustomer?.id, discountAmount, rawSubtotal, method, received, change, redeemPoints, 'pos', roundingDifference);
      setLastSale(sale); setIsCheckoutOpen(false); clearCart(); setManualDiscount(null); setRedeemPoints(0); setSelectedCustomer(null); setIsReceiptOpen(true);
    } catch (e) { alert("Transaction failed."); } finally { setIsProcessing(false); }
  };

  return (
    <div className="flex flex-col lg:flex-row h-full overflow-hidden bg-white md:-m-6">
      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden relative border-r border-slate-200">
        <div className="px-6 py-4 bg-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
            <h2 className="text-2xl font-black text-slate-900 hidden md:block uppercase tracking-tight">{t('pos.newOrder')}</h2>
            <div className="flex space-x-2">
               <button onClick={() => setIsRecallModalOpen(true)} className="flex items-center px-4 py-2 rounded-full text-sm font-bold border bg-orange-50 text-orange-700 border-orange-200 hover:bg-orange-100 transition-all">
                 <ClipboardList className="w-4 h-4 mr-2" /> Recall {heldOrders.length > 0 && <span className="ml-2 bg-orange-200 text-orange-800 px-1.5 rounded-full text-xs">{heldOrders.length}</span>}
               </button>
               <button onClick={() => setIsAiModalOpen(true)} className="flex items-center px-4 py-2 bg-indigo-50 text-indigo-700 border border-indigo-100 rounded-full hover:bg-indigo-100 transition-all text-sm font-bold">
                  <Sparkles className="w-4 h-4 mr-2" /> AI Assistant
               </button>
            </div>
          </div>
          <div className="flex items-center space-x-3">
             <button onClick={() => setIsCustomerModalOpen(true)} className={`flex items-center px-5 py-2.5 rounded-full shadow-sm font-bold text-sm border transition-all ${selectedCustomer ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-700 border-slate-200'}`}>
              <User className="w-4 h-4 mr-2" /> {selectedCustomer ? selectedCustomer.name : 'Select Customer'}
            </button>
          </div>
        </div>
        <div className="flex-1 overflow-hidden relative">
           <ProductGrid 
             products={branchProducts.map(p => ({ ...p, displayPrice: getDynamicPrice(p) }))} 
             categories={categories}
             searchTerm={searchTerm} setSearchTerm={setSearchTerm}
             onScanClick={() => setIsScannerOpen(true)}
             onScan={(code) => setSearchTerm(code)}
             onProductSelect={handleProductSelect}
           />
        </div>
      </div>
      <div className={`fixed inset-0 z-40 bg-white lg:relative lg:translate-x-0 lg:w-[400px] xl:w-[450px] shadow-2xl lg:shadow-none ${isCartOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
         <CartSidebar 
            isOpen={isCartOpen} onClose={() => setIsCartOpen(false)}
            selectedCustomer={selectedCustomer} onRemoveCustomer={() => setSelectedCustomer(null)}
            onHoldOrder={() => holdCurrentOrder(selectedCustomer)} onCheckout={() => setIsCheckoutOpen(true)}
            onDiscountClick={() => setIsDiscountModalOpen(true)}
            subtotal={rawSubtotal} discount={discountAmount} tax={0} total={finalTotal} roundingDifference={roundingDifference} settings={settings}
         />
      </div>
      <CheckoutModal isOpen={isCheckoutOpen} onClose={() => setIsCheckoutOpen(false)} total={finalTotal} onProcessPayment={handleProcessPayment} selectedCustomer={selectedCustomer} isProcessing={isProcessing} settings={settings} />
      <ReceiptModal isOpen={isReceiptOpen} onClose={() => setIsReceiptOpen(false)} sale={lastSale} settings={settings} />
      <CustomerModal isOpen={isCustomerModalOpen} onClose={() => setIsCustomerModalOpen(false)} customers={customers} onSelectCustomer={(c) => { setSelectedCustomer(c); setIsCustomerModalOpen(false); }} />
      <DiscountModal isOpen={isDiscountModalOpen} onClose={() => setIsDiscountModalOpen(false)} onApplyDiscount={setManualDiscount} currencySymbol={settings?.currencySymbol} />
      <RecallModal isOpen={isRecallModalOpen} onClose={() => setIsRecallModalOpen(false)} heldOrders={heldOrders} onRecall={(id) => { recallOrder(id); setIsRecallModalOpen(false); }} onDiscard={discardHeldOrder} />
      <AiAssistant isOpen={isAiModalOpen} onClose={() => setIsAiModalOpen(false)} inventory={branchProducts} onAddItemsToCart={(items) => items.forEach(est => { const p = branchProducts.find(x => x.id === est.matchedProductId); if(p) addToCart({...p, price: getDynamicPrice(p)}, Math.ceil(est.estimatedQuantity)) })} />
      <BarcodeScanner isOpen={isScannerOpen} onClose={() => setIsScannerOpen(false)} onScan={(code) => { setSearchTerm(code); setIsScannerOpen(false); }} />
      {productForSelector && <VariantSelectorModal product={productForSelector} isOpen={!!productForSelector} onClose={() => setProductForSelector(null)} onConfirm={handleConfirmSelection} formatPrice={formatPrice} />}
    </div>
  );
};
